import json
import os
OUT=os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','specs')+os.sep
A="fill='#f5b942'"
def arrowdown(x,y,d='0.1'): return f"<g data-in='{d}'><path d='M{x} {y} V{y+24}' stroke='#f5b942' stroke-width='5'/><path d='M{x-10} {y+20} L{x+10} {y+20} L{x} {y+36} z' fill='#f5b942'/></g>"
def arrowright(x,y,d='0.1',l=40): return f"<g data-in='{d}'><path d='M{x} {y} H{x+l-14}' stroke='#f5b942' stroke-width='5'/><path d='M{x+l-18} {y-10} L{x+l-18} {y+10} L{x+l} {y} z' fill='#f5b942'/></g>"
def box(x,y,w,h,label,d,fs=22,stroke='#6f86bb',fill='#13285e',color='#eef3ff',sub=None):
    t=f"<g data-in='{d}'><rect x='{x}' y='{y}' width='{w}' height='{h}' rx='12' fill='{fill}' stroke='{stroke}' stroke-width='3'/><text x='{x+w/2}' y='{y+h/2+(fs*0.35 if not sub else -2)}' fill='{color}' font-size='{fs}' font-weight='700' text-anchor='middle'>{label}</text>"
    if sub: t+=f"<text x='{x+w/2}' y='{y+h/2+24}' fill='#a9b9de' font-size='17' text-anchor='middle'>{sub}</text>"
    return t+"</g>"
person=lambda x,y,c='#eef3ff':f"<g fill='{c}'><circle cx='{x}' cy='{y}' r='9'/><rect x='{x-8}' y='{y+12}' width='16' height='30' rx='6'/></g>"

